function PortfolioScroller({ projects, title }) {
    try {
        const [currentIndex, setCurrentIndex] = React.useState(0);
        const [showModal, setShowModal] = React.useState(false);
        const [selectedProject, setSelectedProject] = React.useState(null);
        const [itemsPerView, setItemsPerView] = React.useState(3);
        const scrollContainerRef = React.useRef(null);
        const startX = React.useRef(0);
        const isDragging = React.useRef(false);

        React.useEffect(() => {
            const updateItemsPerView = () => {
                if (window.innerWidth < 768) {
                    setItemsPerView(1);
                } else if (window.innerWidth < 1024) {
                    setItemsPerView(2);
                } else {
                    setItemsPerView(3);
                }
            };

            updateItemsPerView();
            window.addEventListener('resize', updateItemsPerView);
            return () => window.removeEventListener('resize', updateItemsPerView);
        }, []);

        const maxIndex = Math.max(0, projects.length - itemsPerView);

        const nextSlide = () => {
            setCurrentIndex(prev => Math.min(prev + 1, maxIndex));
        };

        const prevSlide = () => {
            setCurrentIndex(prev => Math.max(prev - 1, 0));
        };

        const handleProjectClick = (project) => {
            setSelectedProject(project);
            setShowModal(true);
        };

        const isImageUrl = (url) => {
            if (!url) return false;
            return /\.(jpe?g|png|gif|webp|svg|bmp|avif)(\?.*)?$/i.test(url);
        };

        const isVideoUrl = (url) => {
            if (!url) return false;
            return /\.(mp4|webm|ogg)(\?.*)?$/i.test(url);
        };

        const handleTouchStart = (e) => {
            startX.current = e.touches[0].clientX;
            isDragging.current = true;
        };

        const handleTouchMove = (e) => {
            if (!isDragging.current) return;
        };

        const handleTouchEnd = (e) => {
            if (!isDragging.current) return;
            isDragging.current = false;
            
            const endX = e.changedTouches[0].clientX;
            const diffX = startX.current - endX;
            
            if (Math.abs(diffX) > 50) {
                if (diffX > 0) {
                    nextSlide();
                } else {
                    prevSlide();
                }
            }
        };

        return (
            <div id='projects' data-name="portfolio-scroller" data-file="lib/components/PortfolioScroller.js" className="relative overflow-hidden mb-12 md:mb-16 py-20">
                <div className="glass-orb-container">
                    <div className="glass-orb glass-orb-scroller-1"></div>
                    <div className="glass-orb glass-orb-scroller-2"></div>
                </div>
                <h2 className="text-2xl md:text-4xl font-bold mb-6 md:mb-8 text-center px-4 relative z-10">{title}</h2>
                
                <div className="relative z-10">
                    <div 
                        ref={scrollContainerRef}
                        className="overflow-hidden"
                        onTouchStart={handleTouchStart}
                        onTouchMove={handleTouchMove}
                        onTouchEnd={handleTouchEnd}
                    >
                        <div 
                            className="flex transition-transform duration-300 ease-in-out"
                            style={{ transform: `translateX(-${currentIndex * (100 / itemsPerView)}%)` }}
                        >
                            {projects.map((project, index) => (
                                <div 
                                    key={index} 
                                    className={`flex-shrink-0 px-2 md:px-4 ${
                                        itemsPerView === 1 ? 'w-full' : 
                                        itemsPerView === 2 ? 'w-1/2' : 'w-1/3'
                                    }`}
                                >
                                    <div 
                                        className="glass-portfolio-card rounded-xl overflow-hidden cursor-pointer"
                                        onClick={() => handleProjectClick(project)}
                                    >
                                        <img src={project.image} alt={project.title} className="w-full h-40 md:h-48 object-cover" />
                                        <div className="p-4 md:p-6">
                                            <div className="text-xs md:text-sm text-gray-400 mb-2">{project.category}</div>
                                            <h3 className="text-lg md:text-xl font-bold mb-2 md:mb-3">{project.title}</h3>
                                            <p className="text-gray-300 text-xs md:text-sm leading-relaxed">{project.description}</p>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    <button 
                        onClick={prevSlide}
                        disabled={currentIndex === 0}
                        className="absolute left-4 md:left-4 top-1/2 transform -translate-y-1/2 glass-nav-btn text-gray-900 w-8 h-8 md:w-12 md:h-12 rounded-full flex items-center justify-center cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed transition-all duration-300 z-10"
                    >
                        <i className="fas fa-chevron-left text-sm md:text-base"></i>
                    </button>

                    <button 
                        onClick={nextSlide}
                        disabled={currentIndex === maxIndex}
                        className="absolute right-4 md:right-4 top-1/2 transform -translate-y-1/2 glass-nav-btn text-gray-900 w-8 h-8 md:w-12 md:h-12 rounded-full flex items-center justify-center cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed transition-all duration-300 z-10"
                    >
                        <i className="fas fa-chevron-right text-sm md:text-base"></i>
                    </button>
                </div>

                <div className="flex justify-center mt-4 md:mt-6 space-x-2">
                    {Array.from({ length: maxIndex + 1 }).map((_, index) => (
                        <button
                            key={index}
                            onClick={() => setCurrentIndex(index)}
                            className={`w-2 h-2 md:w-3 md:h-3 rounded-full transition-colors ${
                                index === currentIndex ? 'bg-white' : 'bg-gray-600'
                            }`}
                        />
                    ))}
                </div>

                {showModal && selectedProject && (
                    <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-50 p-2 md:p-4">
                        <div className="glass-modal rounded-xl md:rounded-2xl max-w-6xl w-full max-h-[95vh] md:max-h-[92vh] overflow-hidden">
                            <div className="flex justify-between items-center p-4 md:p-6 border-b border-white/10">
                                <h3 className="text-lg md:text-2xl font-bold text-white pr-4">{selectedProject.title}</h3>
                                <button 
                                    onClick={() => setShowModal(false)}
                                    className="text-gray-400 hover:text-white text-xl md:text-2xl flex-shrink-0 cursor-pointer"
                                >
                                    <i className="fas fa-times"></i>
                                </button>
                            </div>
                            <div className="p-4 md:p-6">
                                {isVideoUrl(selectedProject.demoUrl) ? (
                                    <video
                                        src={selectedProject.demoUrl}
                                        className="w-full h-64 md:h-[32rem] rounded-lg object-contain"
                                        autoPlay
                                        loop
                                        muted
                                        playsInline
                                    />
                                ) : isImageUrl(selectedProject.demoUrl) ? (
                                    <img
                                        src={selectedProject.demoUrl}
                                        alt={selectedProject.title}
                                        className="w-full h-64 md:h-[32rem] rounded-lg object-contain"
                                    />
                                ) : (
                                <iframe
                                    src={selectedProject.demoUrl}
                                    className="w-full h-64 md:h-[32rem] rounded-lg"
                                    frameborder="0"
                                    allow="fullscreen; accelerometer; gyroscope; magnetometer; vr; xr; xr-spatial-tracking; autoplay; camera; microphone"
                                    allowfullscreen="true"
                                    webkitallowfullscreen="true"
                                    mozallowfullscreen="true"
                                    oallowfullscreen="true"
                                    msallowfullscreen="true"
                                    title={`${selectedProject.title}`}
                                />
                                )}
                                <div className="mt-3 md:mt-4 flex items-center justify-between gap-4">
                                    <div>
                                        <p className="text-gray-300 text-sm md:text-base">{selectedProject.description}</p>
                                        <div className="mt-2 text-xs md:text-sm text-gray-400">Category: {selectedProject.category}</div>
                                    </div>
                                    {selectedProject.link && (
                                        <a
                                            href={selectedProject.link}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            className="flex-shrink-0 inline-flex items-center gap-2 bg-white text-black px-4 py-2 rounded-lg font-semibold text-sm hover:bg-gray-200 transition-colors"
                                        >
                                            <i className="fas fa-external-link-alt"></i>
                                            Visit Project
                                        </a>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        );
    } catch (error) {
        console.error('PortfolioScroller component error:', error);
        reportError(error);
    }
}